    // ESTADO DEL CATÁLOGO
    let currentFilterCategory = 'Todos';
    let currentSearchQuery = '';
    let visibleCatalogCount = 36;
    const CATALOG_BATCH_SIZE = 36;

    // ESTADO DEL CARRITO REACTIVO
    let cart = [
      {
        id: PRODUCTS_DATA[0].id,
        title: PRODUCTS_DATA[0].title,
        price: PRODUCTS_DATA[0].price,
        qty: 1,
        image: PRODUCTS_DATA[0].image,
        unit: PRODUCTS_DATA[0].unit
      }
    ];

    let cartZone = 100000; // Bogotá por defecto ($100k)
    let currentPdpProduct = PRODUCTS_DATA[0];

    // INICIALIZACIÓN
    document.addEventListener("DOMContentLoaded", () => {
      renderCatalog(true);
      updateCartUI();
    });

    // ESCAPAR HTML
    function escapeHtml(str) {
      if (!str) return '';
      return String(str)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#039;');
    }

    // FILTRO Y BÚSQUEDA DEL CATÁLOGO
    function getFilteredProducts() {
      return PRODUCTS_DATA.filter(p => {
        const matchCat = (currentFilterCategory === 'Todos') || (p.category === currentFilterCategory);
        if (!matchCat) return false;
        if (!currentSearchQuery) return true;
        const q = currentSearchQuery.toLowerCase();
        return p.title.toLowerCase().includes(q) || 
               p.sku.toLowerCase().includes(q) || 
               p.subcat.toLowerCase().includes(q);
      });
    }

    // RENDERIZADO DEL CATÁLOGO CON RENDIMIENTO ÓPTIMO
    function renderCatalog(resetCount = true) {
      if (resetCount) {
        visibleCatalogCount = CATALOG_BATCH_SIZE;
      }

      const filtered = getFilteredProducts();
      const grid = document.getElementById('homeProductsGrid');
      const counterHint = document.getElementById('catalogCounterHint');
      const btnLoadMore = document.getElementById('btnLoadMore');
      const paginationWrap = document.getElementById('catalogPaginationWrap');

      if (!grid) return;

      if (filtered.length === 0) {
        grid.innerHTML = `
          <div class="empty-catalog-msg">
            <div style="font-size: 38px; margin-bottom: 10px;">🔍</div>
            <h3 style="font-size: 17px; font-weight: 800; color: #0f172a; margin-bottom: 6px;">No se encontraron productos</h3>
            <p style="font-size: 13.5px; color: #64748b; margin-bottom: 16px;">No hay resultados que coincidan con "${escapeHtml(currentSearchQuery)}" en esta categoría.</p>
            <button type="button" class="btn-load-more-products" onclick="clearCatalogSearch()">Ver Todos los 486 Productos</button>
          </div>
        `;
        if (paginationWrap) paginationWrap.style.display = 'none';
        return;
      }

      if (paginationWrap) paginationWrap.style.display = 'flex';

      const itemsToShow = filtered.slice(0, visibleCatalogCount);
      let html = '';

      itemsToShow.forEach(product => {
        const inCartItem = cart.find(item => item.id === product.id);
        const inCartQty = inCartItem ? inCartItem.qty : 0;
        
        let inCartHtml = '';
        if (inCartQty > 0) {
          inCartHtml = `
            <div class="card-in-cart-pill active" id="in-cart-${product.id}">
              <span>🛒 En pedido: <strong>${inCartQty} uds</strong></span>
              <button type="button" class="btn-card-remove-item" onclick="removeFromCart('${product.id}')" title="Quitar del carrito">✕ Quitar</button>
            </div>
          `;
        } else {
          inCartHtml = `<div class="card-in-cart-pill" id="in-cart-${product.id}"></div>`;
        }

        html += `
          <div class="p-card-store" data-category="${product.category}" id="card-${product.id}">
            <div class="p-card-img-wrap" onclick="openPdpWithProduct('${product.id}')">
              <img src="${product.image}" alt="${escapeHtml(product.title)}" loading="lazy" onerror="this.src='https://detalshop.com/cdn/shop/files/logo_detal_shop_color.png'">
              <span class="p-card-badge">${product.badge}</span>
            </div>
            <div class="p-card-cat">
              <span>${product.subcat}</span>
              <span style="font-size:9.5px; color:#16a34a; font-weight:800;">INVIMA OK</span>
            </div>
            <div class="p-card-title" onclick="openPdpWithProduct('${product.id}')" title="${escapeHtml(product.title)}">${product.title}</div>
            <div class="p-card-rating">${product.rating}</div>
            
            <div class="p-card-price-row">
              <div class="p-card-price">$${product.price.toLocaleString('es-CO')} COP</div>
              <div class="p-card-unit">${product.unit}</div>
            </div>
            <div class="p-card-tier-hint">${product.tierHint}</div>

            <!-- CONTROLES PARA AGREGAR MÚLTIPLES ITEMS DIRECTAMENTE -->
            <div class="card-add-controls">
              <div class="card-stepper">
                <button type="button" class="btn-card-step" onclick="changeCardQty('${product.id}', -1)" title="Disminuir">-</button>
                <input type="number" id="qty-${product.id}" class="input-card-qty" value="1" min="1" max="999">
                <button type="button" class="btn-card-step" onclick="changeCardQty('${product.id}', 1)" title="Aumentar">+</button>
              </div>
              <button type="button" class="btn-card-add" onclick="addCardQtyToCart('${product.id}')" title="Agregar cantidad seleccionada al pedido">
                🛒 + Agregar
              </button>
            </div>

            <!-- INDICADOR DE ESTADO EN CARRITO Y BOTÓN QUITAR DIRECTO -->
            <div id="in-cart-wrap-${product.id}">
              ${inCartHtml}
            </div>

            <!-- CHIPS DE CANTIDAD RÁPIDA B2B -->
            <div class="card-bulk-chips">
              <span style="font-size:10px; font-weight:800; color:#64748b; margin-right:2px;">Rápido:</span>
              <button type="button" class="chip-qty" onclick="setAndAddQty('${product.id}', 1)">+1</button>
              <button type="button" class="chip-qty" onclick="setAndAddQty('${product.id}', 5)">+5</button>
              <button type="button" class="chip-qty" onclick="setAndAddQty('${product.id}', 10)">+10</button>
              <button type="button" class="btn-card-pdp" onclick="openPdpWithProduct('${product.id}')">Ficha 📄</button>
            </div>
          </div>
        `;
      });

      grid.innerHTML = html;

      // Actualizar contador y botón de paginación
      if (counterHint) {
        counterHint.textContent = `Mostrando ${itemsToShow.length} de ${filtered.length} productos oficiales`;
      }

      if (btnLoadMore) {
        if (itemsToShow.length >= filtered.length) {
          btnLoadMore.style.display = 'none';
        } else {
          btnLoadMore.style.display = 'inline-flex';
          const remaining = filtered.length - itemsToShow.length;
          const nextBatch = Math.min(CATALOG_BATCH_SIZE, remaining);
          btnLoadMore.querySelector('span').textContent = `📦 Cargar Más Productos (+${nextBatch})`;
        }
      }
    }

    function loadMoreProducts() {
      visibleCatalogCount += CATALOG_BATCH_SIZE;
      renderCatalog(false);
    }

    function handleCatalogSearch(val) {
      currentSearchQuery = (val || '').trim();
      const clearBtn = document.getElementById('catalogSearchClear');
      if (clearBtn) {
        clearBtn.style.display = currentSearchQuery ? 'flex' : 'none';
      }
      renderCatalog(true);
    }

    function clearCatalogSearch() {
      currentSearchQuery = '';
      const input = document.getElementById('catalogSearchInput');
      if (input) input.value = '';
      const clearBtn = document.getElementById('catalogSearchClear');
      if (clearBtn) clearBtn.style.display = 'none';
      renderCatalog(true);
    }

    // FILTRO DE CATEGORÍAS DEL CATÁLOGO
    function filterHomeCatalog(category, btnElement) {
      currentFilterCategory = category;
      if (btnElement) {
        document.querySelectorAll('.cat-tab-pill').forEach(b => b.classList.remove('active'));
        btnElement.classList.add('active');
      }
      renderCatalog(true);
    }

    // CAMBIO DE VISTAS (HOME / PDP / TRACKING)
    function switchView(viewName) {
      document.querySelectorAll('.page-view-block').forEach(el => el.classList.remove('active'));
      document.querySelectorAll('.nav-tab-btn').forEach(el => el.classList.remove('active'));

      if (viewName === 'home') {
        document.getElementById('viewHome').classList.add('active');
        document.getElementById('tabBtnHome').classList.add('active');
        window.scrollTo({ top: 0, behavior: 'smooth' });
      } else if (viewName === 'pdp') {
        document.getElementById('viewPdp').classList.add('active');
        document.getElementById('tabBtnPdp').classList.add('active');
        window.scrollTo({ top: 0, behavior: 'smooth' });
      } else if (viewName === 'track') {
        document.getElementById('viewTrack').classList.add('active');
        document.getElementById('tabBtnTrack').classList.add('active');
        window.scrollTo({ top: 0, behavior: 'smooth' });
      }
    }

    function scrollToCatalog() {
      const el = document.getElementById('catalogSection');
      if (el) el.scrollIntoView({ behavior: 'smooth' });
    }

    // SELECTOR DE DISPOSITIVO (DESKTOP / MOBILE 390px)
    function setDevice(device) {
      const wrapper = document.getElementById('mainWebsite');
      const btnDesk = document.getElementById('btnDesk');
      const btnMob = document.getElementById('btnMob');

      if (device === 'mobile') {
        wrapper.classList.add('mobile-mode');
        btnMob.classList.add('active');
        btnDesk.classList.remove('active');
      } else {
        wrapper.classList.remove('mobile-mode');
        btnDesk.classList.add('active');
        btnMob.classList.remove('active');
      }
    }

    // ========================================================================
    // CONTROLES DE CANTIDAD EN CADA TARJETA DE PRODUCTO
    // ========================================================================
    function changeCardQty(productId, delta) {
      const input = document.getElementById('qty-' + productId);
      if (!input) return;
      let val = parseInt(input.value) || 1;
      val += delta;
      if (val < 1) val = 1;
      if (val > 999) val = 999;
      input.value = val;
    }

    function addCardQtyToCart(productId) {
      const input = document.getElementById('qty-' + productId);
      const qty = input ? parseInt(input.value) || 1 : 1;
      addToCart(productId, qty);
    }

    function setAndAddQty(productId, qty) {
      addToCart(productId, qty);
    }

    // ========================================================================
    // LÓGICA DEL CARRITO REACTIVO
    // ========================================================================
    function addToCart(productId, qty) {
      qty = parseInt(qty) || 1;
      const product = PRODUCTS_DATA.find(p => p.id === productId);
      if (!product) return;

      const existingIndex = cart.findIndex(item => item.id === productId);
      if (existingIndex > -1) {
        cart[existingIndex].qty += qty;
      } else {
        cart.push({
          id: product.id,
          title: product.title,
          price: product.price,
          qty: qty,
          image: product.image,
          unit: product.unit
        });
      }

      updateCartUI();
      showToastNotification(qty, product.title, product.price * qty);
    }

    // ELIMINAR Y ACTUALIZAR PRODUCTOS DEL CARRITO (SOPORTA PRODUCT ID E ÍNDICE)
    function removeFromCart(productIdOrIndex) {
      let removedTitle = 'Producto';
      if (typeof productIdOrIndex === 'number' || (!isNaN(productIdOrIndex) && typeof productIdOrIndex !== 'string')) {
        const idx = parseInt(productIdOrIndex);
        if (cart[idx]) {
          removedTitle = cart[idx].title;
          cart.splice(idx, 1);
        }
      } else {
        const idx = cart.findIndex(i => i.id === productIdOrIndex);
        if (idx > -1) {
          removedTitle = cart[idx].title;
          cart.splice(idx, 1);
        }
      }
      updateCartUI();
      showToastNotification(0, removedTitle + ' eliminado del pedido', 0, true);
    }

    function removeCartItem(identifier) {
      removeFromCart(identifier);
    }

    function updateCartItemQty(identifier, delta) {
      let item = null;
      if (typeof identifier === 'number') {
        item = cart[identifier];
      } else {
        item = cart.find(i => i.id === identifier);
      }
      if (!item) return;

      item.qty += delta;
      if (item.qty <= 0) {
        removeFromCart(item.id);
      } else {
        updateCartUI();
      }
    }

    function clearFullCart() {
      if (cart.length === 0) return;
      if (confirm('¿Deseas vaciar todos los productos del carrito de compras?')) {
        cart = [];
        updateCartUI();
        showToastNotification(0, 'Carrito vaciado por completo', 0, true);
      }
    }

    function setCartZone(amount) {
      cartZone = amount;
      document.getElementById('btnZoneBog').classList.toggle('active', amount === 100000);
      document.getElementById('btnZoneNac').classList.toggle('active', amount === 200000);
      updateCartUI();
    }

    function updateCartUI() {
      const totalUnits = cart.reduce((sum, item) => sum + item.qty, 0);
      const totalPrice = cart.reduce((sum, item) => sum + (item.qty * item.price), 0);

      // 1. Badges y contadores
      const hCount = document.getElementById('headerCartCount');
      if (hCount) hCount.textContent = totalUnits;
      const tCount = document.getElementById('toolbarCartCount');
      if (tCount) tCount.textContent = totalUnits;
      
      const drawerTitle = document.getElementById('drawerHeaderTitle');
      if (drawerTitle) {
        drawerTitle.innerHTML = `
          <span>Tu Carrito (${totalUnits} item${totalUnits !== 1 ? 's' : ''})</span>
          ${totalUnits > 0 ? '<button type="button" class="btn-clear-cart" onclick="clearFullCart()" title="Vaciar todo el pedido">🗑️ Vaciar</button>' : ''}
        `;
      }

      const drawerTotal = document.getElementById('drawerTotalText');
      if (drawerTotal) drawerTotal.textContent = `$${totalPrice.toLocaleString('es-CO')} COP`;

      // 2. Renderizar items en Cart Drawer
      const container = document.getElementById('drawerItemsList');
      if (container) {
        if (cart.length === 0) {
          container.innerHTML = `
            <div style="text-align:center; padding: 40px 20px; color:#64748b;">
              <div style="font-size:36px; margin-bottom:12px;">🛒</div>
              <p style="font-weight:700;">Tu carrito está vacío.</p>
              <p style="font-size:12px; margin-top:4px;">Agrega productos desde el catálogo de 486 items para comenzar.</p>
            </div>
          `;
        } else {
          let html = '';
          cart.forEach((item) => {
            const itemSubtotal = item.qty * item.price;
            html += `
              <div class="drawer-cart-item" id="drawer-item-${item.id}">
                <div class="drawer-cart-img">
                  <img src="${item.image}" alt="${escapeHtml(item.title)}" onerror="this.src='https://detalshop.com/cdn/shop/files/logo_detal_shop_color.png'">
                </div>
                <div class="drawer-cart-info">
                  <div class="drawer-cart-title">${item.title}</div>
                  <div class="drawer-cart-price">$${item.price.toLocaleString('es-CO')} COP <span style="font-size:11px; color:#64748b;">(${item.unit})</span></div>
                  <div style="display:flex; align-items:center; gap:8px; margin-top:4px;">
                    <div class="drawer-item-stepper">
                      <button type="button" class="btn-drawer-step" onclick="updateCartItemQty('${item.id}', -1)" title="Restar 1">-</button>
                      <input type="text" readonly class="drawer-step-val" value="${item.qty}">
                      <button type="button" class="btn-drawer-step" onclick="updateCartItemQty('${item.id}', 1)" title="Sumar 1">+</button>
                    </div>
                    <span style="font-size:11.5px; font-weight:800; color:#0f172a;">$${itemSubtotal.toLocaleString('es-CO')}</span>
                  </div>
                </div>
                <button type="button" class="btn-drawer-delete" onclick="removeFromCart('${item.id}')" title="Eliminar este producto del pedido">
                  🗑️ Quitar
                </button>
              </div>
            `;
          });
          container.innerHTML = html;
        }
      }

      // 3. Actualizar indicadores en las tarjetas visibles del catálogo
      document.querySelectorAll('.p-card-store').forEach(card => {
        const pid = card.id.replace('card-', '');
        const inCart = cart.find(i => i.id === pid);
        const wrap = document.getElementById('in-cart-wrap-' + pid);
        if (wrap) {
          if (inCart) {
            wrap.innerHTML = `
              <div class="card-in-cart-pill active" id="in-cart-${pid}">
                <span>🛒 En pedido: <strong>${inCart.qty} uds</strong></span>
                <button type="button" class="btn-card-remove-item" onclick="removeFromCart('${pid}')">✕ Quitar</button>
              </div>
            `;
          } else {
            wrap.innerHTML = `<div class="card-in-cart-pill" id="in-cart-${pid}"></div>`;
          }
        }
      });

      // 4. Barra de progreso de pedido mínimo
      const bar = document.getElementById('drawerProgressBar');
      const alertText = document.getElementById('drawerAlertText');
      const btn = document.getElementById('btnCheckoutFigma');

      const pct = Math.min(100, (totalPrice / cartZone) * 100);
      if (bar) bar.style.width = pct + '%';

      const zoneName = cartZone === 100000 ? 'Bogotá' : 'a nivel Nacional';

      if (totalPrice >= cartZone) {
        if (bar) bar.className = 'min-progress-bar success';
        if (alertText) {
          alertText.className = 'min-alert-text success';
          alertText.innerHTML = `🎉 ¡Felicitaciones! Has superado el pedido mínimo de $${cartZone.toLocaleString('es-CO')} COP para despacho gratis en ${zoneName}.`;
        }
        if (btn) {
          btn.className = 'btn-drawer-checkout';
          btn.textContent = '[ Proceder al Pago Seguro 🔒 ]';
        }
      } else {
        const missing = cartZone - totalPrice;
        if (bar) bar.className = 'min-progress-bar';
        if (alertText) {
          alertText.className = 'min-alert-text';
          alertText.innerHTML = `⚠️ Saldo actual: $${totalPrice.toLocaleString('es-CO')} / Meta: $${cartZone.toLocaleString('es-CO')} (Faltan $${missing.toLocaleString('es-CO')} COP para habilitar despacho en ${zoneName})`;
        }
        if (btn) {
          btn.className = 'btn-drawer-checkout disabled';
          btn.textContent = `[ Mínimo requerido: $${cartZone.toLocaleString('es-CO')} ]`;
        }
      }

      // 5. Barra Fija Inferior
      const sBadge = document.getElementById('stickyTotalBadge');
      if (sBadge) sBadge.textContent = `${totalUnits} Item${totalUnits !== 1 ? 's' : ''}`;
      const sPrice = document.getElementById('stickyTotalPrice');
      if (sPrice) sPrice.textContent = `$${totalPrice.toLocaleString('es-CO')} COP`;
      const sCount = document.getElementById('stickyBtnCount');
      if (sCount) sCount.textContent = totalUnits;

      const stickyStatus = document.getElementById('stickyStatusText');
      if (stickyStatus) {
        if (totalPrice >= cartZone) {
          stickyStatus.textContent = `🎉 ¡Despacho habilitado para ${zoneName}!`;
        } else {
          const missing = cartZone - totalPrice;
          stickyStatus.textContent = `Faltan $${missing.toLocaleString('es-CO')} COP para pedido mínimo en ${zoneName}`;
        }
      }
    }

    // FLOATING TOAST NOTIFICATION
    function showToastNotification(qty, title, subtotal, isRemoval = false) {
      const container = document.getElementById('toastContainer');
      if (!container) return;
      const toast = document.createElement('div');
      toast.className = 'floating-toast';
      if (isRemoval) {
        toast.style.borderLeftColor = '#ef4444';
        toast.innerHTML = `
          <div style="font-size:20px;">🗑️</div>
          <div style="flex:1;">
            <div style="font-weight:800; font-size:12.5px; color:#f87171;">Producto Eliminado</div>
            <div style="font-size:12px; color:#cbd5e1;">${title}</div>
          </div>
          <button class="btn-toast-view" onclick="openCartDrawer()">Ver Carrito 🛒</button>
        `;
      } else {
        toast.innerHTML = `
          <div style="font-size:20px;">✅</div>
          <div style="flex:1;">
            <div style="font-weight:800; font-size:12.5px;">¡Agregado al Pedido!</div>
            <div style="font-size:12px; color:#94a3b8;">${qty}x ${title} ($${subtotal.toLocaleString('es-CO')} COP)</div>
          </div>
          <button class="btn-toast-view" onclick="openCartDrawer()">Ver Carrito 🛒</button>
        `;
      }

      container.appendChild(toast);

      setTimeout(() => {
        toast.style.opacity = '0';
        toast.style.transform = 'translateY(10px)';
        toast.style.transition = 'all 0.3s ease';
        setTimeout(() => toast.remove(), 300);
      }, 3500);
    }

    // DRAWER OPEN / CLOSE
    function openCartDrawer() {
      document.getElementById('cartDrawerOverlay').classList.add('active');
    }

    function closeCartDrawer(e) {
      if (!e || e.target === document.getElementById('cartDrawerOverlay') || e.target.classList.contains('drawer-close-btn')) {
        document.getElementById('cartDrawerOverlay').classList.remove('active');
      }
    }

    function proceedCheckoutFigma() {
      const totalPrice = cart.reduce((sum, item) => sum + (item.qty * item.price), 0);
      if (totalPrice < cartZone) {
        alert(`⚠️ Para continuar, el pedido debe ser de mínimo $${cartZone.toLocaleString('es-CO')} COP. Te sugerimos agregar productos desde el catálogo.`);
        return;
      }

      const cedula = document.getElementById('cedulaNitDrawer').value.trim();
      if (!cedula) {
        alert('Por favor ingrese Cédula / NIT para facturación electrónica DIAN');
        document.getElementById('cedulaNitDrawer').focus();
        return;
      }

      alert(`✅ VALIDACIÓN EXITOSA:
• Cédula/NIT DIAN: ${cedula}
• Total Pedido: $${totalPrice.toLocaleString('es-CO')} COP
• Destino: ${cartZone === 100000 ? 'Bogotá' : 'Nacional'}
• Avanzando a pasarela de pago segura.`);
    }

    // ========================================================================
    // FICHA DE PRODUCTO INTERACTIVA (PDP)
    // ========================================================================
    function openPdpWithProduct(productId) {
      const product = PRODUCTS_DATA.find(p => p.id === productId);
      if (!product) return;
      currentPdpProduct = product;

      document.getElementById('pdpBreadTitle').textContent = product.title;
      document.getElementById('pdpBreadCat').textContent = product.subcat;
      document.getElementById('pdpTitle').textContent = product.title;
      document.getElementById('pdpBadge').textContent = product.badge;
      document.getElementById('pdpSku').textContent = 'SKU: ' + product.sku;
      document.getElementById('pdpInvima').textContent = product.invima;
      document.getElementById('pdpPrice').textContent = `$${product.price.toLocaleString('es-CO')} COP`;

      // Precios de escala
      document.getElementById('tPrice1').textContent = `$${product.price.toLocaleString('es-CO')} COP`;
      document.getElementById('tPrice2').textContent = `$${Math.round(product.price * 0.9).toLocaleString('es-CO')} COP`;
      document.getElementById('tPrice3').textContent = `$${Math.round(product.price * 0.85).toLocaleString('es-CO')} COP`;
      document.getElementById('tPrice4').textContent = `$${Math.round(product.price * 0.8).toLocaleString('es-CO')} COP`;

      document.getElementById('pdpQtyInput').value = 1;
      updatePdpTotal();

      // Galería
      document.getElementById('pdpMainImg').src = product.image;
      document.getElementById('thumb0').src = product.image;
      document.getElementById('galleryViewCaption').textContent = "Vista 1: Frontal Institucional";

      // Reset thumbs
      document.querySelectorAll('.pdp-thumb-card').forEach((tc, idx) => {
        tc.classList.toggle('active', idx === 0);
      });

      // Modal data
      document.getElementById('modalPdfTitle').textContent = `Ficha Técnica Oficial — ${product.title}`;
      document.getElementById('modalPdfInvima').textContent = product.invima;
      document.getElementById('modalPdfPh').textContent = product.specs.ph || '7.0 (Neutro)';
      document.getElementById('modalPdfBio').textContent = product.specs.bio || '≥ 90%';

      switchView('pdp');
    }

    function switchPdpImage(index) {
      document.querySelectorAll('.pdp-thumb-card').forEach((el, idx) => {
        el.classList.toggle('active', idx === index);
      });

      const mainImg = document.getElementById('pdpMainImg');
      const caption = document.getElementById('galleryViewCaption');

      if (index === 0) {
        mainImg.src = currentPdpProduct.image;
        caption.textContent = "Vista 1: Frontal Institucional";
      } else if (index === 1) {
        mainImg.src = "../05_Insumos_y_Documentos/detalgraf_detergente_20l_vista2_perspectiva.jpg";
        caption.textContent = "Vista 2: Perspectiva 3/4 & Nivel";
      } else if (index === 2) {
        mainImg.src = "../05_Insumos_y_Documentos/detalgraf_detergente_20l_vista3_etiqueta.jpg";
        caption.textContent = "Vista 3: Etiqueta y Registro INVIMA";
      } else if (index === 3) {
        mainImg.src = "../05_Insumos_y_Documentos/detalgraf_detergente_20l_vista4_estiba.jpg";
        caption.textContent = "Vista 4: Presentación en Estiba / Almacén B2B";
      }
    }

    function changePdpQty(delta) {
      const input = document.getElementById('pdpQtyInput');
      let val = parseInt(input.value) || 1;
      val += delta;
      if (val < 1) val = 1;
      input.value = val;
      updatePdpTotal();
    }

    function updatePdpTotal() {
      const qty = parseInt(document.getElementById('pdpQtyInput').value) || 1;
      let unitPrice = currentPdpProduct.price;

      // Descuentos por volumen
      document.querySelectorAll('.tier-row').forEach(r => r.classList.remove('active'));
      if (qty >= 24) {
        unitPrice = Math.round(currentPdpProduct.price * 0.80);
        document.getElementById('tier4').classList.add('active');
      } else if (qty >= 12) {
        unitPrice = Math.round(currentPdpProduct.price * 0.85);
        document.getElementById('tier3').classList.add('active');
      } else if (qty >= 5) {
        unitPrice = Math.round(currentPdpProduct.price * 0.90);
        document.getElementById('tier2').classList.add('active');
      } else {
        document.getElementById('tier1').classList.add('active');
      }

      const subtotal = qty * unitPrice;
      document.getElementById('pdpSubtotalDisplay').textContent = `Subtotal: $${subtotal.toLocaleString('es-CO')} COP`;
    }

    function addPdpToCart() {
      const qty = parseInt(document.getElementById('pdpQtyInput').value) || 1;
      addToCart(currentPdpProduct.id, qty);
    }

    // MODAL PDF
    function openPdfModal() {
      document.getElementById('pdfModalOverlay').classList.add('active');
    }
    function closePdfModal() {
      document.getElementById('pdfModalOverlay').classList.remove('active');
    }

